    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return new TextDecoder().decode(bytes);
  }

  // Helper: encode bytes to base64
  function bytesToBase64(bytes: Uint8Array): string {
    let binary = "";
    for (const b of bytes) {
      binary += String.fromCharCode(b);
    }
    return btoa(binary);
  }

  // Helper: decode base64 to bytes
  function base64ToBytes(b64: string): Uint8Array {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  // Get or create salt
  let saltStr = await storage.get(SALT_KEY);
  if (saltStr === undefined) {
    const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
    saltStr = bytesToBase64(salt);
    await storage.set(SALT_KEY, saltStr);
  }
  const salt = base64ToBytes(saltStr);

  // Derive key
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(masterPassword),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  const key = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: salt as BufferSource,
      iterations: PBKDF2_ITERATIONS,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );

  // Helper: get storage key for a secret
  function secretKey(owner: string, name: string): string {
    return SECRET_PREFIX + toBase64(owner + "\0" + name);
  }

  // Helper: get storage key for an index
  function indexKey(owner: string): string {
    return INDEX_PREFIX + toBase64(owner);
  }

  // Helper: get AAD for encryption
  function getAAD(owner: string, name: string): Uint8Array {
    return new TextEncoder().encode(owner + "\0" + name);
