    const stored = await storage.get(secretKey(owner, name));
    if (stored === undefined) return undefined;

    const blob = base64ToBytes(stored);
    if (blob.length < IV_LENGTH + 16) {
      throw new Error("Invalid secret data");
    }

    const iv = blob.slice(0, IV_LENGTH);
    const ciphertext = blob.slice(IV_LENGTH);
    const aad = getAAD(owner, name);

    let decrypted: ArrayBuffer;
    try {
      decrypted = await crypto.subtle.decrypt(
        {
          name: "AES-GCM",
          iv: iv as BufferSource,
          additionalData: aad as BufferSource,
        },
        key,
        ciphertext as BufferSource
      );
    } catch {
      throw new Error("Failed to decrypt secret: possible tampering or incorrect password");
    }

    return new TextDecoder().decode(decrypted);
  }

  async function list(owner: string): Promise<string[]> {
    const indexStr = await storage.get(indexKey(owner));
    if (indexStr === undefined) return [];

    try {
      const names = JSON.parse(indexStr) as string[];
      return names.sort();
    } catch {
      return [];
    }
  }

  async function remove(owner: string, name: string): Promise<boolean> {
    const key = secretKey(owner, name);
    const stored = await storage.get(key);
    if (stored === undefined) return false;

    await storage.delete(key);
    await removeFromIndex(owner, name);
    return true;
  }

  async function addToIndex(owner: string, name: string): Promise<void> {
    const key = indexKey(owner);
    const existing = await storage.get(key);
    let names: string[];
    if (existing === undefined) {
      names = [];
    } else {
      try {
        names = JSON.parse(existing) as string[];
      } catch {
        names = [];
      }
    }
    if (!names.includes(name)) {
      names.push(name);
    }
    await storage.set(key, JSON.stringify(names));
  }

  async function removeFromIndex(owner: string, name: string): Promise<void> {
    const key = indexKey(owner);
    const existing = await storage.get(key);
    if (existing === undefined) return;

    let names: string[];
    try {
      names = JSON.parse(existing) as string[];
    } catch {
      return;
    }

    const idx = names.indexOf(name);
    if (idx === -1) return;
    names.splice(idx, 1);

    if (names.length === 0) {
      await storage.delete(key);
    } else {
      await storage.set(key, JSON.stringify(names));
    }
  }

  return { put, get, list, remove };
}
