    {
      name: "PBKDF2",
      salt: salt.buffer,  // Use .buffer to get ArrayBuffer
      iterations: ITERATIONS,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  function secretKey(owner: string, name: string): string {
    return SECRET_PREFIX + strToB64(owner + "\0" + name);
  }

  function indexKey(owner: string): string {
    return INDEX_PREFIX + strToB64(owner);
  }

